5	/// Live, whole-home energy picture aggregated by [EnergyRole].
6	///
7	/// Computed from the current [DeviceView]s by [EnergySummary.fromDevices].
8	/// All power fields are **watts** (Matter reports milliwatts; we convert).
9	///
10	/// Sign convention — positive = power flowing *into* the house node:
11	///   • grid:    `activePower > 0` = importing (buying);  `< 0` = exporting.
12	///   • battery: `activePower > 0` = charging (load);     `< 0` = discharging.
13	///   • pv / car / heatpump: magnitude only (PV always produces, the two
14	///     consumers always consume).
15	///
16	/// Multiple devices may carry the same role; their power is summed.
17	@immutable
18	class EnergySummary {
19	  const EnergySummary({
20	    this.gridImport = 0,
21	    this.gridExport = 0,
22	    this.pvProduction = 0,
23	    this.batteryCharge = 0,
24	    this.batteryDischarge = 0,
25	    this.batterySocPercent,
26	    this.carCharging = 0,
27	    this.heatPump = 0,
28	    this.gridCount = 0,
29	    this.pvCount = 0,
30	    this.batteryCount = 0,
31	    this.carCount = 0,
32	    this.heatPumpCount = 0,
33	  });
34	
35	  final double gridImport;       // W drawn from the grid
36	  final double gridExport;       // W pushed to the grid
37	  final double pvProduction;     // W produced by PV
38	  final double batteryCharge;    // W flowing into the battery
39	  final double batteryDischarge; // W flowing out of the battery
40	  final int?   batterySocPercent;
41	  final double carCharging;      // W consumed by car chargers
42	  final double heatPump;         // W consumed by heat pumps
43	
44	  // How many devices are tagged with each role (drives which nodes render).
45	  final int gridCount;
46	  final int pvCount;
47	  final int batteryCount;
48	  final int carCount;
49	  final int heatPumpCount;
50	
51	  bool get hasGrid    => gridCount    > 0;
52	  bool get hasPv      => pvCount      > 0;
53	  bool get hasBattery => batteryCount > 0;
54	  bool get hasCar     => carCount     > 0;
55	  bool get hasHeatPump => heatPumpCount > 0;
56	
57	  /// True when at least one device carries an energy role — gates the overview.
58	  bool get hasAnyRole =>
59	      hasGrid || hasPv || hasBattery || hasCar || hasHeatPump;
60	
61	  /// Total power the house is consuming right now (energy balance):
62	  /// production + imports + battery discharge − exports − battery charge.
63	  double get houseLoad =>
64	      pvProduction + gridImport + batteryDischarge - gridExport - batteryCharge;
65	
66	  /// Consumption not attributed to a monitored consumer role (the "rest of
67	  /// home" node).  Clamped at 0 — a negative value just means the monitored
68	  /// consumers exceed the computed balance (measurement skew).
69	  double get restOfHome {
70	    final rest = houseLoad - carCharging - heatPump;
71	    return rest > 0 ? rest : 0;
72	  }
73	
74	  /// Folds the current device views into a summary. Devices without a role
75	  /// (or without live power) contribute nothing to the sums but a tagged
76	  /// device still counts toward node presence.
77	  factory EnergySummary.fromDevices(Iterable<DeviceView> devices) {
78	    double gridNet = 0, pv = 0, batNet = 0, car = 0, heat = 0;
79	    var gridN = 0, pvN = 0, batN = 0, carN = 0, heatN = 0;
80	    var socSum = 0, socCount = 0;
81	
82	    for (final d in devices) {
83	      // Skip unreachable devices — their last-known reading isn't current, so
84	      // it must not be presented as a live value in the overview.
85	      if (!d.isOnline) continue;
86	      final w = (d.activePowerMw ?? 0) / 1000.0;
87	      switch (d.energyRole) {
88	        case EnergyRole.grid:
89	          gridNet += w;
90	          gridN++;
91	        case EnergyRole.pv:
92	          pv += w.abs();
93	          pvN++;
94	        case EnergyRole.homeBattery:
95	          batNet += w;
96	          batN++;
97	          final soc = d.batteryPercent;
98	          if (soc != null) { socSum += soc; socCount++; }
99	        case EnergyRole.carCharger:
100	          car += w.abs();
101	          carN++;
102	        case EnergyRole.heatPump:
103	          heat += w.abs();
104	          heatN++;
105	        case EnergyRole.none:
106	          break;
107	      }
108	    }
109	
110	    return EnergySummary(
111	      gridImport:       gridNet > 0 ? gridNet : 0,
112	      gridExport:       gridNet < 0 ? -gridNet : 0,
113	      pvProduction:     pv,
114	      batteryCharge:    batNet > 0 ? batNet : 0,
115	      batteryDischarge: batNet < 0 ? -batNet : 0,
116	      batterySocPercent: socCount > 0 ? (socSum / socCount).round() : null,
117	      carCharging:      car,
118	      heatPump:         heat,
119	      gridCount:        gridN,
120	      pvCount:          pvN,
121	      batteryCount:     batN,
122	      carCount:         carN,
123	      heatPumpCount:    heatN,
124	    );
125	  }
126	}
