void hnd_energy_history_get(coap_resource_t *resource, coap_session_t *session,
                            const coap_pdu_t *request, const coap_string_t *query,
                            coap_pdu_t *response)
{
    coap_bin_const_t tok = coap_pdu_get_token(request);
    coap_async_t *async = coap_find_async(session, tok);

    if (async) {
        cluster_dump_result_t *res =
            (cluster_dump_result_t *)coap_async_get_app_data(async);
        if (!res) return;   /* still pending (a CON retransmit) — worker will finish */
        /* Triggered re-run: deliver the encoded EnergyHistory. Zero length is a
         * valid empty message. libcoap frees `async` after this returns. */
        coap_send_proto(resource, session, request, response,
                        res->json ? (const uint8_t *)res->json : (const uint8_t *)"",
                        res->json_len);
        free(res->json);
        coap_session_release(res->session);
        free(res);
        return;
    }

    /* First request: parse the window, ACK now via the async, aggregate on a
     * worker (SD read + parse can take seconds — must not block the CoAP task). */
    int64_t now = time(NULL);
    int64_t to  = q_int(query, "to",   now);
    int64_t from = q_int(query, "from", to - 86400);   /* default: last 24 h */
    int     bucket = (int)q_int(query, "bucket", ENERGY_DEFAULT_BUCKET_SEC);
    bool    want_series = q_int(query, "series", 1) != 0;   /* series=0 → skip device breakdown */

    async = coap_register_async(session, request, 0);
    if (!async) {
        coap_pdu_set_code(response, COAP_RESPONSE_CODE_SERVICE_UNAVAILABLE);
        return;
    }
    energy_job_t *job = (energy_job_t *)calloc(1, sizeof(*job));
    if (!job) {
        coap_free_async(session, async);
        coap_pdu_set_code(response, COAP_RESPONSE_CODE_INTERNAL_ERROR);
        return;
    }
    job->token_len = tok.length > sizeof(job->token) ? sizeof(job->token) : tok.length;
    if (job->token_len) memcpy(job->token, tok.s, job->token_len);
    job->session = coap_session_reference(session);
    job->from = from;
    job->to   = to;
    job->bucket = bucket;
    job->want_series = want_series;

    if (!energy_worker_ready() || xQueueSend(s_energy_q, &job, 0) != pdTRUE) {
        ESP_LOGE(TAG, "energy history: worker unavailable or queue full");
        coap_session_release(job->session);
        free(job);
        coap_free_async(session, async);
        coap_pdu_set_code(response, COAP_RESPONSE_CODE_SERVICE_UNAVAILABLE);
        return;
    }
    /* No inline reply — the async ACKs, the worker delivers the real response. */

