301	
302	/* Parse a decimal "<key>=<n>" param out of a CoAP URI-Query string. */
303	static int64_t q_int(const coap_string_t *q, const char *key, int64_t def)
304	{
305	    if (!q || !q->s) return def;
306	    const char *s = (const char *)q->s;
307	    size_t klen = strlen(key);
308	    for (const char *p = strstr(s, key); p; p = strstr(p + 1, key)) {
309	        if ((p == s || p[-1] == '&') && p[klen] == '=')
310	            return strtoll(p + klen + 1, NULL, 10);
311	    }
312	    return def;
313	}
