315	/* ── Worker + handler (CoAP separate response) ───────────────────────────── */
316	
317	typedef struct {
318	    coap_session_t *session;
319	    uint8_t         token[8];
320	    size_t          token_len;
321	    int64_t         from, to;
322	    int             bucket;
323	    bool            want_series;   /* false → skip per-device breakdown (series=0) */
324	} energy_job_t;
325	
326	/* Single persistent worker fed by a queue. Created once with a PSRAM stack
327	 * (xTaskCreateWithCaps) so it costs ~zero scarce internal RAM — the old
328	 * per-request xTaskCreate needed an 8 KB *internal* stack, which failed with
329	 * "5.00 Internal Server Error" once subscriptions drove internal free down to
330	 * ~12 KB. It never self-deletes, avoiding the vTaskDeleteWithCaps self-delete
331	 * path (which spawns an internal cleanup task and abort()s if that fails). */
332	#define ENERGY_Q_DEPTH 4
333	static QueueHandle_t s_energy_q = NULL;
334	
335	static void energy_process(energy_job_t *job)
336	{
337	    uint8_t *buf = NULL;
338	    size_t   len = 0;
339	    flux_EnergyHistory *hist = (flux_EnergyHistory *)calloc(1, sizeof(*hist));
340	    if (hist) {
341	        aggregate(job->from, job->to, job->bucket, job->want_series, hist);
342	        buf = (uint8_t *)malloc(flux_EnergyHistory_size);
343	        if (buf) {
344	            pb_ostream_t os = pb_ostream_from_buffer(buf, flux_EnergyHistory_size);
345	            if (pb_encode(&os, flux_EnergyHistory_fields, hist)) {
346	                len = os.bytes_written;
347	            } else {
348	                ESP_LOGE(TAG, "pb_encode failed: %s", PB_GET_ERROR(&os));
349	                free(buf);
350	                buf = NULL;
351	            }
352	        }
353	        free(hist);
354	    }
355	
356	    notify_t *n = (notify_t *)malloc(sizeof(notify_t));
357	    if (n) {
358	        memset(n, 0, sizeof(*n));
359	        n->type           = NOTIFY_TYPE_ENERGY_HISTORY;
360	        n->md_session     = job->session;
361	        n->md_token_len   = job->token_len;
362	        memcpy(n->md_token, job->token, job->token_len);
363	        n->md_payload     = buf;     /* NULL → reply empty */
364	        n->md_payload_len = len;
365	        if (xQueueSend(flux_coap_notify_queue, &n, pdMS_TO_TICKS(1000)) != pdTRUE) {
366	            free(n);
367	            free(buf);
368	            coap_session_release(job->session);
369	        }
370	    } else {
371	        free(buf);
372	        coap_session_release(job->session);
373	    }
374	    free(job);
375	}
376	
377	static void energy_worker(void *arg)
378	{
379	    (void)arg;
380	    for (;;) {
381	        energy_job_t *job = NULL;
382	        if (xQueueReceive(s_energy_q, &job, portMAX_DELAY) == pdTRUE && job)
383	            energy_process(job);
384	    }
385	}
386	
387	/* Lazily create the queue + persistent PSRAM-stack worker on first use. Safe
388	 * without locking: all CoAP handlers run on the single coap_server task. */
389	static bool energy_worker_ready(void)
390	{
391	    if (s_energy_q) return true;
392	    s_energy_q = xQueueCreate(ENERGY_Q_DEPTH, sizeof(energy_job_t *));
393	    if (!s_energy_q) return false;
394	    if (xTaskCreateWithCaps(energy_worker, "energy_hist", 8192, NULL, 4, NULL,
395	                            MALLOC_CAP_SPIRAM) != pdPASS) {
396	        vQueueDelete(s_energy_q);
397	        s_energy_q = NULL;
398	        return false;
399	    }

