55	  CoapRequest _build(TransportRequest r) {
56	    final uri = endpoint.coapUri(r.path, query: r.query);
57	    switch (r.method) {
58	      case TransportMethod.get:
59	        return CoapRequest.get(uri, accept: _proto);
60	      case TransportMethod.put:
61	        return CoapRequest.put(uri,
62	            payload: r.body ?? Uint8List(0), contentFormat: _proto, accept: _proto);
63	      case TransportMethod.post:
