73	    final timeout = Duration(milliseconds: r.timeoutMs);
74	    CoapResponse resp;
75	    try {
76	      resp = await _client.send(_build(r)).timeout(timeout);
77	    } on TimeoutException {
78	      unawaited(reconnect());
79	      return TransportResponse.unreachable;
80	    } on Exception catch (e) {
81	      if (_disposed) return TransportResponse.unreachable;
82	      if (!r.retryOnConnError) {
83	        unawaited(reconnect());
84	        return TransportResponse.unreachable;
85	      }
86	      debugPrint('InProcessTransport ${r.path}: $e — reconnecting + retry once');
87	      await reconnect();
88	      try {
89	        resp = await _client.send(_build(r)).timeout(timeout);
90	      } on Exception {
91	        return TransportResponse.unreachable;
92	      }
93	    }
94	    return TransportResponse(
95	      ok:      true,
96	      success: resp.code.isSuccess,
97	      payload: Uint8List.fromList(resp.payload),
