102	  Stream<TransportEvent> observe(String path, {Map<String, String>? query}) {
103	    final ctrl = StreamController<TransportEvent>();
104	    CoapObserveClientRelation? rel;
105	
106	    ctrl.onCancel = () {
107	      if (rel != null) {
108	        _relations.remove(rel);
109	        try { _client.cancelObserveProactive(rel!); } on Exception catch (_) {}
110	      }
111	    };
112	
113	    unawaited(() async {
114	      try {
115	        final req = CoapRequest.get(
116	            endpoint.coapUri(path, query: query), accept: _proto);
117	        rel = await _client.observe(req);
118	        _relations.add(rel!);
119	        rel!.listen(
120	          (resp) => ctrl.add(TransportEvent(TransportEventKind.data,
121	              payload: Uint8List.fromList(resp.payload))),
122	          onError: (Object e) =>
123	              ctrl.add(TransportEvent(TransportEventKind.error, error: e.toString())),
124	          onDone: () {
125	            ctrl.add(const TransportEvent(TransportEventKind.done));
126	            if (!ctrl.isClosed) ctrl.close();
127	          },
128	        );
129	      } on Exception catch (e) {
130	        ctrl.add(TransportEvent(TransportEventKind.error, error: e.toString()));
131	        if (!ctrl.isClosed) await ctrl.close();
132	      }
133	    }());
134	
135	    return ctrl.stream;
136	  }
