139	  Future<void> dispose() async {
140	    _disposed = true;
141	    for (final rel in _relations) {
142	      try { _client.cancelObserveReactive(rel); } on Exception catch (_) {}
143	    }
144	    _relations.clear();
145	    _client.close();
146	  }
