84	typedef struct {
85	    uint64_t node_id;
86	    int      cls;
87	    int      cur_bucket;            /* bucket currently accumulating; -1 = unseen */
88	    int      series_idx;            /* index into out->device_series, or -1 (PV only) */
89	    bool     have_import, have_export;
90	    int64_t  base_import, base_export;   /* counter at end of last closed bucket */
91	    int64_t  last_import, last_export;   /* latest counter within current bucket */
92	} dev_state_t;
