94	/* Route a per-bucket counter delta (mWh) into the right proto fields (Wh). */
95	static void route(flux_EnergyBucket *bk, int cls, int64_t imp_mwh, int64_t exp_mwh)
96	{
97	    if (imp_mwh < 0) imp_mwh = 0;   /* guard counter resets / reboots */
98	    if (exp_mwh < 0) exp_mwh = 0;
99	    switch (cls) {
100	        case CLS_GRID:
101	            bk->grid_import_wh += (uint32_t)(imp_mwh / 1000);
102	            bk->grid_export_wh += (uint32_t)(exp_mwh / 1000);
103	            break;
104	        case CLS_PV:
105	            /* Generation lands on different counters by device: a SunSpec
106	             * inverter reports it as export (2.8.0), a smart plug metering a
107	             * balcony PV reports it as import (1.8.0). Sum both — the unused
108	             * counter is ~0 for each — so either convention is captured. */
109	            bk->pv_wh += (uint32_t)((imp_mwh + exp_mwh) / 1000);
110	            break;
111	        case CLS_LOAD:
112	            bk->load_wh += (uint32_t)(imp_mwh / 1000);
113	            break;
114	        case CLS_BATTERY:
115	            bk->battery_charge_wh    += (uint32_t)(imp_mwh / 1000);  /* into battery */
116	            bk->battery_discharge_wh += (uint32_t)(exp_mwh / 1000);  /* out of battery */
117	            break;
118	        default: break;
119	    }
120	}
