122	static void close_bucket(dev_state_t *d, flux_EnergyHistory *out)
123	{
124	    if (d->cur_bucket < 0 || d->cur_bucket >= (int)out->buckets_count) return;
125	    int64_t imp = d->have_import ? d->last_import - d->base_import : 0;
126	    int64_t exp = d->have_export ? d->last_export - d->base_export : 0;
127	    route(&out->buckets[d->cur_bucket], d->cls, imp, exp);
128	    /* Per-device PV breakdown: mirror this device's generation into its own
129	     * series (import + export, matching route() — plug vs inverter counter). */
130	    if (d->cls == CLS_PV && d->series_idx >= 0) {
131	        int64_t i = imp < 0 ? 0 : imp;
132	        int64_t e = exp < 0 ? 0 : exp;
133	        out->device_series[d->series_idx].wh[d->cur_bucket] += (uint32_t)((i + e) / 1000);
134	    }
135	    d->base_import = d->last_import;
136	    d->base_export = d->last_export;
137	}
