139	static dev_state_t *dev_get(dev_state_t *devs, int *n, uint64_t node_id, int cls)
140	{
141	    for (int i = 0; i < *n; i++)
142	        if (devs[i].node_id == node_id) return &devs[i];
143	    if (*n >= ENERGY_MAX_DEVS) return NULL;
144	    dev_state_t *d = &devs[(*n)++];
145	    memset(d, 0, sizeof(*d));
146	    d->node_id = node_id;
147	    d->cls = cls;
148	    d->cur_bucket = -1;
149	    d->series_idx = -1;
150	    return d;
151	}
