153	static void process_row(dev_state_t *devs, int *n_devs, flux_EnergyHistory *out,
154	                        bool want_series,
155	                        uint64_t node_id, int cls, const char *name, int b,
156	                        bool has_imp, int64_t imp, bool has_exp, int64_t exp)
157	{
158	    dev_state_t *d = dev_get(devs, n_devs, node_id, cls);
159	    if (!d) return;
160	
161	    /* A device can be reclassified mid-window (the app changes its energy role,
162	     * e.g. a plug retagged from load to PV); route by the latest class, not the
163	     * first-seen one, so the change takes effect within the window. */
164	    d->cls = cls;
165	
166	    /* Break PV out per inverter (bounded); allocated the first time the device
167	     * is seen as PV. The summed buckets are unchanged. */
168	    if (want_series && cls == CLS_PV && d->series_idx < 0 &&
169	        out->device_series_count < ENERGY_MAX_SERIES) {
170	        int k = out->device_series_count++;
171	        flux_EnergyDeviceSeries *s = &out->device_series[k];
172	        s->node_id  = node_id;
173	        s->cls      = flux_EnergyClass_ENERGY_CLASS_PV;
174	        strlcpy(s->name, name ? name : "", sizeof(s->name));
175	        s->wh_count = out->buckets_count;  /* dense; wh[] zeroed by calloc */
176	        d->series_idx = k;
177	    }
178	
179	    if (d->cur_bucket < 0) {                 /* first row for this device */
180	        d->cur_bucket = b;
181	        if (has_imp) { d->have_import = true; d->base_import = imp; d->last_import = imp; }
182	        if (has_exp) { d->have_export = true; d->base_export = exp; d->last_export = exp; }
183	        return;
184	    }
185	    if (b > d->cur_bucket) {                  /* advanced past the current bucket */
186	        const bool gap = (b - d->cur_bucket) > 1;
187	        close_bucket(d, out);                 /* flush energy accrued in the old bucket */
188	        d->cur_bucket = b;
189	        if (gap) {
190	            /* A whole bucket had no rows — with 10 s sampling that's a real
191	             * outage (e.g. a controller reboot), not normal jitter. Rebase the
192	             * baseline to this reading so the counter growth accumulated during
193	             * the gap isn't dumped into a single bucket as a huge false spike.
194	             * The (genuinely unknown) energy during the gap is dropped. */
195	            if (has_imp) { d->base_import = imp; d->last_import = imp; }
196	            if (has_exp) { d->base_export = exp; d->last_export = exp; }
197	        }
198	    }
199	    if (has_imp) { if (!d->have_import) { d->have_import = true; d->base_import = imp; } d->last_import = imp; }
200	    if (has_exp) { if (!d->have_export) { d->have_export = true; d->base_export = exp; } d->last_export = exp; }
201	}
