203	/* Split a CSV line in place. Returns the field count; cols[] point into line. */
204	static int split_csv(char *line, char *cols[], int max)
205	{
206	    size_t L = strlen(line);
207	    while (L && (line[L - 1] == '\n' || line[L - 1] == '\r')) line[--L] = '\0';
208	    int n = 0;
209	    cols[n++] = line;
210	    for (char *p = line; *p && n < max; p++) {
211	        if (*p == ',') { *p = '\0'; cols[n++] = p + 1; }
212	    }
213	    return n;
214	}
