216	/* ── Aggregation ─────────────────────────────────────────────────────────── */
217	
218	static void aggregate(int64_t from, int64_t to, int bucket_sec, bool want_series,
219	                      flux_EnergyHistory *out)
220	{
221	    if (bucket_sec < ENERGY_MIN_BUCKET_SEC) bucket_sec = ENERGY_DEFAULT_BUCKET_SEC;
222	    if (to <= from) to = from + bucket_sec;
223	
224	    int64_t start = (from / bucket_sec) * bucket_sec;   /* align down */
225	    int64_t span  = to - start;
226	    int n_buckets = (int)((span + bucket_sec - 1) / bucket_sec);
227	    if (n_buckets < 1) n_buckets = 1;
228	    if (n_buckets > ENERGY_MAX_BUCKETS) { n_buckets = ENERGY_MAX_BUCKETS; out->truncated = true; }
229	    int64_t eff_to = start + (int64_t)n_buckets * bucket_sec;
230	
231	    out->start          = start;
232	    out->bucket_seconds = (uint32_t)bucket_sec;
233	    out->from           = from;
234	    out->to             = to;
235	    out->buckets_count  = (pb_size_t)n_buckets;
236	    for (int i = 0; i < n_buckets; i++) {
237	        memset(&out->buckets[i], 0, sizeof(out->buckets[i]));
238	        out->buckets[i].index = (uint32_t)i;
239	    }
240	
241	    static dev_state_t devs[ENERGY_MAX_DEVS];   /* worker task is single-threaded */
242	    int  n_devs = 0;
243	    bool any_unsynced = false;
244	    int  files = 0, rows = 0;
245	
246	    for (int64_t d = (start / 86400) * 86400; d < eff_to; d += 86400) {
247	        char date[9];
248	        struct tm tm;
249	        time_t dd = (time_t)d;
250	        gmtime_r(&dd, &tm);
251	        strftime(date, sizeof(date), "%Y%m%d", &tm);
252	        char path[64];
253	        snprintf(path, sizeof(path), FLUX_ENERGY_DIR "/%s.csv", date);
254	
255	        FILE *f = fopen(path, "r");
256	        if (!f) continue;
257	        files++;
258	
259	        char line[256];
260	        char *cols[FLUX_ELOG_COL_COUNT + 2];
261	        while (fgets(line, sizeof(line), f)) {
262	            if (line[0] == '#') continue;
263	            int nc = split_csv(line, cols, FLUX_ELOG_COL_COUNT + 2);
264	            if (nc < FLUX_ELOG_COL_COUNT) continue;                 /* short/garbled */
265	            if (strcmp(cols[FLUX_ELOG_COL_TIMESTAMP], "timestamp") == 0) continue; /* header */
266	
267	            int64_t ts = iso_to_epoch(cols[FLUX_ELOG_COL_TIMESTAMP]);
268	            if (ts < start || ts >= eff_to) continue;
269	            int cls = class_of(cols[FLUX_ELOG_COL_DEVICE_CLASS]);
270	            if (cls == CLS_NONE) continue;
271	
272	            int b = (int)((ts - start) / bucket_sec);
273	            if (b < 0 || b >= n_buckets) continue;
274	
275	            uint64_t node_id = strtoull(cols[FLUX_ELOG_COL_NODE_ID], NULL, 16);
276	            if (cols[FLUX_ELOG_COL_TIME_SYNCED][0] != '1') any_unsynced = true;
277	
278	            const char *si = cols[FLUX_ELOG_COL_ENERGY_IMPORT_MWH];
279	            const char *se = cols[FLUX_ELOG_COL_ENERGY_EXPORT_MWH];
280	            bool has_imp = si[0] != '\0';
281	            bool has_exp = se[0] != '\0';
282	            int64_t imp = has_imp ? strtoll(si, NULL, 10) : 0;
283	            int64_t exp = has_exp ? strtoll(se, NULL, 10) : 0;
284	
285	            process_row(devs, &n_devs, out, want_series, node_id, cls,
286	                        cols[FLUX_ELOG_COL_DEVICE_NAME], b, has_imp, imp, has_exp, exp);
287	            rows++;
288	        }
289	        fclose(f);
290	    }
291	
292	    for (int i = 0; i < n_devs; i++) close_bucket(&devs[i], out);   /* flush finals */
293	    out->time_synced = !any_unsynced;
294	
295	    ESP_LOGI(TAG, "history: %d bucket(s) @%ds from %d file(s), %d row(s), %d dev(s)%s",
296	             n_buckets, bucket_sec, files, rows, n_devs,
297	             out->truncated ? " [truncated]" : "");

