4	/// One time bucket of the energy-history chart, expressed as **average power in
5	/// watts** over the bucket (so lines read as instantaneous-ish power, kW).
6	///
7	/// The controller reports watt-hours accumulated per bucket; average power is
8	/// `Wh / (bucketSeconds / 3600)`.
9	@immutable
10	class EnergyHistoryPoint {
11	  const EnergyHistoryPoint({
12	    required this.time,
13	    required this.pvW,
14	    required this.gridImportW,
15	    required this.gridExportW,
16	    required this.loadW,
17	  });
18	
19	  final DateTime time;
20	  final double pvW;         // PV generation
21	  final double gridImportW; // drawn from the grid
22	  final double gridExportW; // fed to the grid
23	  final double loadW;       // home consumption
24	
25	  double get maxSeries =>
26	      [pvW, gridImportW, gridExportW, loadW].reduce((a, b) => a > b ? a : b);
27	
28	  /// Whole-home consumption for this bucket (average W), from the energy
29	  /// balance: generation + import − export. Clamped ≥ 0. (Battery isn't in the
30	  /// per-bucket series, so it's omitted here — fine for the price overlay.)
31	  double get consumptionW {
32	    final c = pvW + gridImportW - gridExportW;
33	    return c > 0 ? c : 0;
34	  }
35	}
36	
37	/// One PV inverter's generation over the same time base — average power (W) per
38	/// bucket, index-aligned to [EnergyHistoryData.points].
39	@immutable
40	class PvDeviceSeries {
41	  const PvDeviceSeries({
42	    required this.nodeId,
43	    required this.name,
44	    required this.wattsPerBucket,
45	    required this.kwh,
46	  });
47	
48	  final int nodeId;
49	  final String name;
50	  final List<double> wattsPerBucket;
51	  final double kwh; // window total
52	
53	  double get peakW =>
54	      wattsPerBucket.isEmpty ? 0 : wattsPerBucket.reduce((a, b) => a > b ? a : b);
55	}
