57	/// A decoded, chart-ready energy history: the per-bucket power series plus the
58	/// window totals (kWh) and derived KPIs. Built from the controller's
59	/// [$proto.EnergyHistory]; the UI never sees raw protobuf.
60	@immutable
61	class EnergyHistoryData {
62	  const EnergyHistoryData({
63	    required this.points,
64	    required this.bucket,
65	    required this.timeSynced,
66	    required this.truncated,
67	    required this.pvKwh,
68	    required this.gridImportKwh,
69	    required this.gridExportKwh,
70	    required this.loadKwh,
71	    this.batteryChargeKwh = 0,
72	    this.batteryDischargeKwh = 0,
73	    this.pvSeries = const [],
74	  });
75	
76	  final List<EnergyHistoryPoint> points;
77	  final Duration bucket;
78	  final bool timeSynced; // false → times approximate (pre-SNTP rows)
79	  final bool truncated;  // true → range exceeded the per-response cap
80	
81	  final double pvKwh;
82	  final double gridImportKwh;
83	  final double gridExportKwh;
84	  /// Sum of load-classed devices' consumption (monitored appliances only — not
85	  /// necessarily whole-home; prefer [consumptionKwh] for totals).
86	  final double loadKwh;
87	  final double batteryChargeKwh;
88	  final double batteryDischargeKwh;
89	
90	  /// Per-inverter PV breakdown, when the controller reports it. Empty → only the
91	  /// summed PV total ([pvKwh] / [EnergyHistoryPoint.pvW]) is available.
92	  final List<PvDeviceSeries> pvSeries;
93	
94	  /// True when the controller reported a per-device PV breakdown — then the
95	  /// individual inverter lines are drawn (by device name) instead of the summed
96	  /// "Solar" total. Older firmware reports none → the total line is used.
97	  bool get hasPvBreakdown => pvSeries.isNotEmpty;
98	  bool get isEmpty => points.isEmpty;
99	
100	  /// Peak power across every drawn series — drives the chart's Y scale. When a
101	  /// PV breakdown exists the individual inverter lines (not the summed total)
102	  /// are what's drawn, so scale to those.
103	  double get peakW {
104	    if (points.isEmpty) return 0;
105	    var peak = 0.0;
106	    for (final p in points) {
107	      final consumptionSide =
108	          [p.gridImportW, p.gridExportW, p.loadW].reduce((a, b) => a > b ? a : b);
109	      if (consumptionSide > peak) peak = consumptionSide;
110	      if (!hasPvBreakdown && p.pvW > peak) peak = p.pvW;
111	    }
112	    if (hasPvBreakdown) {
113	      for (final s in pvSeries) {
114	        if (s.peakW > peak) peak = s.peakW;
115	      }
116	    }
117	    return peak;
118	  }
119	
120	  /// Convert a bucket's **average power (W)** into the **energy (kWh)** it
121	  /// represents over one bucket's duration — the unit the history chart plots
122	  /// (kWh per bucket = avg-kW × bucket-hours).
123	  double kwhFromW(double avgW) => avgW * bucket.inSeconds / 3600000.0;
124	
125	  /// Consumption energy (kWh) in bucket [i].
126	  double bucketConsumptionKwh(int i) => kwhFromW(points[i].consumptionW);
127	
128	  /// Largest single-bucket value (kWh) across every drawn series — drives the
129	  /// chart's Y scale. Mirrors [peakW] but in per-bucket energy.
130	  double get peakKwh => kwhFromW(peakW);
131	
132	  /// Whole-home consumption over the window, from the energy balance:
133	  ///   consumption = generated + imported + battery discharge
134	  ///               − exported − battery charge
135	  /// This is grounded in the grid + PV (+ battery) meters, so it's robust even
136	  /// when individual loads aren't metered (unlike [loadKwh]). Clamped ≥ 0.
137	  double get consumptionKwh {
138	    final c = pvKwh +
139	        gridImportKwh +
140	        batteryDischargeKwh -
141	        gridExportKwh -
142	        batteryChargeKwh;
143	    return c > 0 ? c : 0;
144	  }
145	
146	  /// Share of consumption met from own generation/storage rather than bought
147	  /// from the grid, 0–100: `(consumed − imported) / consumed`. Null when there
148	  /// was no consumption.
149	  int? get selfSufficiencyPercent {
150	    final c = consumptionKwh;
151	    if (c <= 0) return null;
152	    final selfConsumed = c - gridImportKwh;
153	    return ((selfConsumed / c).clamp(0.0, 1.0) * 100).round();
154	  }
155	
156	  factory EnergyHistoryData.fromProto($proto.EnergyHistory h) {
157	    final bucketSec = h.bucketSeconds == 0 ? 900 : h.bucketSeconds;
158	    final start = h.start.toInt(); // epoch seconds of bucket 0
159	    final perHour = bucketSec / 3600.0; // fraction of an hour per bucket
160	
161	    // Wh → average W over the bucket.
162	    double watts(int wh) => wh / perHour;
163	
164	    final points = <EnergyHistoryPoint>[];
165	    var pvWh = 0, impWh = 0, expWh = 0, loadWh = 0, batChgWh = 0, batDisWh = 0;
166	    for (final b in h.buckets) {
167	      pvWh += b.pvWh;
168	      impWh += b.gridImportWh;
169	      expWh += b.gridExportWh;
170	      loadWh += b.loadWh;
171	      batChgWh += b.batteryChargeWh;
172	      batDisWh += b.batteryDischargeWh;
173	      points.add(EnergyHistoryPoint(
174	        time: DateTime.fromMillisecondsSinceEpoch(
175	            (start + b.index * bucketSec) * 1000),
176	        pvW: watts(b.pvWh),
177	        gridImportW: watts(b.gridImportWh),
178	        gridExportW: watts(b.gridExportWh),
179	        loadW: watts(b.loadWh),
180	      ));
181	    }
182	    // Per-device PV breakdown (index-aligned to buckets), if the controller
183	    // reported it. Each series' wh[] is dense and aligned to h.buckets by index.
184	    final pvSeries = <PvDeviceSeries>[];
185	    for (final s in h.deviceSeries) {
186	      if (s.cls != $proto.EnergyClass.ENERGY_CLASS_PV) continue;
187	      var total = 0;
188	      final watts = <double>[];
189	      for (var i = 0; i < points.length; i++) {
190	        final wh = i < s.wh.length ? s.wh[i] : 0;
191	        total += wh;
192	        watts.add(wh / perHour);
193	      }
194	      pvSeries.add(PvDeviceSeries(
195	        nodeId: s.nodeId.toInt(),
196	        name: s.name.isNotEmpty ? s.name : 'PV ${s.nodeId.toInt()}',
197	        wattsPerBucket: watts,
198	        kwh: total / 1000.0,
199	      ));
200	    }
201	
202	    return EnergyHistoryData(
203	      points: points,
204	      bucket: Duration(seconds: bucketSec),
205	      timeSynced: h.timeSynced,
206	      truncated: h.truncated,
207	      pvKwh: pvWh / 1000.0,
208	      gridImportKwh: impWh / 1000.0,
209	      gridExportKwh: expWh / 1000.0,
210	      loadKwh: loadWh / 1000.0,
211	      batteryChargeKwh: batChgWh / 1000.0,
212	      batteryDischargeKwh: batDisWh / 1000.0,
213	      pvSeries: pvSeries,
214	    );
215	  }
216	}
